<!doctype html><html lang="en"><head><meta charset="UTF-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#26384b;padding:30px}h1{text-align:center;color:#176b81}h2{text-align:center}p{line-height:1.9;font-size:14px}table{width:100%;border-collapse:collapse}td{padding:10px;border-bottom:1px solid #ddd}.sign{margin-top:100px;text-align:right}</style></head><body><h1>School Management System</h1><h2>{{ $title }}</h2><p>Certificate No: {{ $student->admission_no }}-{{ strtoupper($type) }}<br>Issued: {{ now()->format('d-m-Y') }}</p><p>This is to certify that <strong>{{ $student->first_name }} {{ $student->last_name }}</strong>, child of <strong>{{ $student->father_name }}</strong>, is recorded in the school register under admission number <strong>{{ $student->admission_no }}</strong>.</p>@if($type === 'leaving')<p>This school leaving certificate records the student's enrollment details below for transfer or withdrawal.</p>@elseif($type === 'character')<p>This character certificate is provided for school verification. Conduct remarks: ______________________________________________</p>@else<p>This bonafide certificate confirms the student's recorded enrollment in the session and class stated below.</p>@endif<table><tr><td>Admission Date</td><td>{{ $student->admission_date->format('d-m-Y') }}</td></tr><tr><td>Date of Birth</td><td>{{ $student->date_of_birth->format('d-m-Y') }}</td></tr><tr><td>Academic Session</td><td>{{ $options['academic_session_id'][$student->academic_session_id] ?? 'Unassigned' }}</td></tr><tr><td>Class / Section</td><td>{{ $options['class_id'][$student->class_id] ?? 'Unassigned' }} / {{ $options['section_id'][$student->section_id] ?? 'Unassigned' }}</td></tr><tr><td>Current Status</td><td>{{ $student->status }}</td></tr></table><p class="sign">____________________________<br>Authorized Signature &amp; School Stamp</p></body></html>
